-- Phase 3.4: immutable, idempotent pedagogical mission events.
create table if not exists public.mission_events (
 server_sequence bigint generated by default as identity primary key,event_id uuid not null,user_id uuid not null references auth.users(id) on delete cascade,
 device_id uuid not null,platform text not null check(platform in ('web','android','ios')),event_kind text not null check(event_kind in ('assignment','lifecycle')),
 payload jsonb not null,created_at timestamptz not null default now(),unique(user_id,event_id));
create index if not exists mission_events_user_sequence on public.mission_events(user_id,server_sequence);
create unique index if not exists mission_events_user_payload_id on public.mission_events(user_id,(payload->>'id'));
alter table public.mission_events enable row level security;
drop policy if exists "mission_events_select_own" on public.mission_events;
create policy "mission_events_select_own" on public.mission_events for select to authenticated using((select auth.uid())=user_id);
create or replace function public.submit_mission_event(p_event_id uuid,p_device_id uuid,p_platform text,p_payload jsonb)
returns table(server_sequence bigint,accepted boolean,total_xp integer) language plpgsql security definer set search_path='' as $$
declare v_user uuid:=auth.uid();v_kind text:=p_payload->>'kind';v jsonb:=p_payload->'value';v_seq bigint;v_assignment jsonb;v_terminal boolean;
begin
 if v_user is null then raise exception 'Authentication required';end if;
 if p_platform not in ('web','android','ios') or v_kind not in ('assignment','lifecycle') or jsonb_typeof(v)<>'object' then raise exception 'Invalid mission event';end if;
 if length(v::text)>20000 or coalesce(v->>'id','')='' or char_length(v->>'id')>300 then raise exception 'Invalid identifier';end if;
 if v_kind='assignment' then
  if v->>'cadence' not in ('daily','weekly','thematic','open') or v->>'category' not in ('practice','reading','continuity','reinforcement','thematic')
   or v->>'metric' not in ('questions','lessons','reviews','checkpoints','plan-steps','chapters','activity')
   or coalesce((v->>'target')::integer,0) not between 1 and 100 or coalesce((v->>'baseline')::integer,-1)<0 then raise exception 'Invalid assignment';end if;
 else
  if v->>'kind' not in ('mission_started','mission_progressed','mission_completed','mission_expired','mission_cancelled')
   or coalesce(v->>'missionId','')='' or coalesce((v->>'observedProgress')::integer,-1)<0 then raise exception 'Invalid lifecycle';end if;
  select e.payload into v_assignment from public.mission_events e where e.user_id=v_user and e.event_kind='assignment' and e.payload->>'id'=v->>'missionId' order by e.server_sequence limit 1;
  if v_assignment is null then raise exception 'Mission assignment not found';end if;
  select exists(select 1 from public.mission_events e where e.user_id=v_user and e.event_kind='lifecycle' and e.payload->>'missionId'=v->>'missionId' and e.payload->>'kind' in ('mission_completed','mission_expired','mission_cancelled')) into v_terminal;
  if v_terminal and v->>'kind' in ('mission_completed','mission_expired','mission_cancelled') then raise exception 'Mission already terminal';end if;
  if v->>'kind'='mission_completed' and (v->>'observedProgress')::integer<(v_assignment->>'target')::integer then raise exception 'Mission target not reached';end if;
 end if;
 insert into public.mission_events(event_id,user_id,device_id,platform,event_kind,payload) values(p_event_id,v_user,p_device_id,p_platform,v_kind,v)
 on conflict do nothing returning mission_events.server_sequence into v_seq;
 if v_seq is null then select e.server_sequence into v_seq from public.mission_events e where e.user_id=v_user and (e.event_id=p_event_id or e.payload->>'id'=v->>'id') order by e.server_sequence limit 1;
  return query select v_seq,false,coalesce((select s.total_xp from public.user_stats s where s.user_id=v_user),0);return;end if;
 return query select v_seq,true,coalesce((select s.total_xp from public.user_stats s where s.user_id=v_user),0);
end;$$;
revoke all on function public.submit_mission_event(uuid,uuid,text,jsonb) from public;
grant execute on function public.submit_mission_event(uuid,uuid,text,jsonb) to authenticated;
